const j = $json;
let handle = "";
const keys = ["Instagram","instagram","IG","Insta","instagram_url","instagramUrl","instagramUsername"];
for (const k of keys) { if (j[k]) { handle = String(j[k]); break; } }
if (!handle) { for (const [k, v] of Object.entries(j)) { if (typeof v === "string" && /instagram\.com/i.test(v)) { handle = v; break; } } }
if (handle) { const m = handle.match(/instagram\.com\/([A-Za-z0-9_.]+)/i); if (m) handle = m[1]; handle = handle.replace(/^@/, "").replace(/\/$/, "").trim(); }
const businessName = j["Nom"] || j["Titre"] || j["Name"] || j["businessName"] || "";
const adresse = j["Adresse"] || j["adresse"] || j["Address"] || "";
const siteWeb = j["Site Web"] || j["SiteWeb"] || j["Website"] || j["site"] || "";
const email = (j["Email"] || j["email"] || j["E-mail"] || j["Mail"] || "").toString().trim();
return { json: { row_number: j.row_number, businessName: businessName, adresse: adresse, siteWeb: siteWeb, igHandleFromSheet: handle, email: email, FeedStatus: j["FeedStatus"] || "" } };

// Deterministic Instagram-handle discovery. NO LLM.
// Input = raw HTML of the lead's own website (HTTP node, responseFormat=text -> $json.data).
// A business almost always links its own Instagram from its own site.
// Guard: many 'Site Web' values in Sortie2 are third-party aggregators (bluepillow,
// booking, tripadvisor...). Their pages link THEIR OWN Instagram, so we only keep a
// handle that is plausibly related to the business name, otherwise we return nothing
// and let the Apify name-search decide.
const RESERVED = new Set(["p","reel","reels","explore","stories","tv","s","accounts","about","directory","legal","web","developer","help","privacy","terms","download","instagram"]);
const AGGREGATORS = ["bluepillow","booking","airbnb","expedia","tripadvisor","thefork","lafourchette","ubereats","deliveroo","justeat","yelp","pagesjaunes","petitfute","google","facebook","instagram","wix","wordpress","shopify","squarespace","hostelworld","trivago","agoda","vrbo","abritel"];
const STOP = new Set(["le","la","les","au","aux","du","de","des","chez","une","un","the","and","for","with","restaurant","restaurants","brasserie","pizzeria","boulangerie","patisserie","snack","villa","hotel","room","rooms","bedroom","apartment","appartement","studio","maison","house","lodge","gite","chambre","chambres","resort","guesthouse"]);

function clean(h){ return (h||"").toString().trim().replace(/^@/,"").replace(/^https?:\/\/(www\.)?instagram\.com\//i,"").replace(/[\/?#].*$/,"").replace(/\/$/,"").trim(); }
function norm(s){ return (s||"").toString().toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9]/g,""); }
function tokens(s){
  return (s||"").toString().toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"")
    .split(/[^a-z0-9]+/).filter(t => t.length >= 4 && !STOP.has(t));
}

let lead;
try { lead = $("Extract Lead").item.json; } catch (e) { lead = $("Extract Lead").first().json; }

const src = $json || {};
let raw = "";
if (typeof src.data === "string") raw = src.data;
else if (typeof src.body === "string") raw = src.body;
else raw = JSON.stringify(src);

const siteWeb = (lead.siteWeb || "").toString();
const siteHost = norm((siteWeb.match(/^(?:https?:\/\/)?(?:www\.)?([^\/?#]+)/i) || ["",""])[1]);
const isAggregator = AGGREGATORS.some(a => siteHost.indexOf(a) !== -1);

let siteHandle = "";
if (!isAggregator) {
  const counts = {};
  const re = /instagram\.com\/([A-Za-z0-9_.]{2,30})/ig;
  let m;
  while ((m = re.exec(raw))) {
    const c = clean(m[1]);
    if (!c) continue;
    const lc = c.toLowerCase();
    if (RESERVED.has(lc)) continue;
    if (AGGREGATORS.some(a => lc.indexOf(a) !== -1)) continue;
    counts[c] = (counts[c] || 0) + 1;
  }
  const ranked = Object.keys(counts).sort((a,b) => counts[b] - counts[a]);
  const candidate = ranked[0] || "";
  const bizTokens = tokens(lead.businessName);
  const nCand = norm(candidate);
  const related = bizTokens.length > 0 && bizTokens.some(t => nCand.indexOf(t) !== -1 || siteHost.indexOf(t) !== -1);
  siteHandle = related ? candidate : "";
}

const sheetHandle = clean(lead.igHandleFromSheet || "");
const finalHandle = sheetHandle || siteHandle;

return { json: {
  row_number: lead.row_number,
  email: lead.email,
  businessName: lead.businessName,
  adresse: lead.adresse,
  siteWeb: siteWeb,
  igHandle: finalHandle,
  igHandleSource: sheetHandle ? "sheet" : (siteHandle ? "website" : (isAggregator ? "none-aggregator-site" : "none"))
} };

const p = $json;
const bio = p.biography || "";
const cat = p.businessCategoryName || "";
const followers = p.followersCount || "";
let caps = "";
try { caps = (p.latestPosts || []).map(x => x.caption).filter(Boolean).slice(0,6).join(" | "); } catch (e) {}
const ctx = "Source: compte Instagram existant.\nBio: " + bio + "\nCategorie: " + cat + "\nAbonnes: " + followers + "\nCaptions recentes: " + caps;
return { json: { accountContext: ctx, sourceType: "instagram" } };

let html = $json.data || $json.body || "";
if (typeof html !== "string") { html = JSON.stringify(html); }
let text = html.replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<style[\s\S]*?<\/style>/gi, " ").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
text = text.slice(0, 1500);
const site = $("Route Source").item.json.siteWeb || "";
const ctx = text ? ("Source: site web (" + site + ").\nContenu: " + text) : "Source: aucune donnee en ligne. Base-toi sur le nom, le secteur et l adresse de l etablissement.";
return { json: { accountContext: ctx, sourceType: "website" } };

const lead = $('Route Source').first().json;
const norm = s => (s||'').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]/g,'');
const RES = new Set(['p','reel','reels','explore','stories','tv','s','accounts']);
const target = norm(lead.businessName);
const claude = norm(lead.igHandle);
let best = { handle:'', score:0 };
for (const it of $input.all()) {
  const j = it.json || {};
  let user = (j.username || j.ownerUsername || (j.user&&j.user.username) || '').toString().replace(/^@/,'').trim();
  if (!user || RES.has(user.toLowerCase())) continue;
  const full = norm(j.fullName || j.full_name || j.name || (j.user&&(j.user.full_name||j.user.fullName)) || '');
  const u = norm(user);
  let score = 0;
  if (target && (u.includes(target) || target.includes(u))) score += 3;
  if (target && full && (full.includes(target) || target.includes(full))) score += 3;
  if (claude && u === claude) score += 4;
  if (j.is_verified || j.isVerified) score += 1;
  if (score > best.score) best = { handle:user, score };
}
let handle = best.score >= 3 ? best.handle : '';
if (!handle && claude && !RES.has(claude)) handle = lead.igHandle;
return [{ json: { row_number: lead.row_number, businessName: lead.businessName, adresse: lead.adresse, siteWeb: lead.siteWeb, igHandle: handle, igSearchScore: best.score } }];

function llmText(j){
  if (typeof j.stdout === 'string' && j.stdout.trim()) return j.stdout;
  if (Array.isArray(j.content)) return j.content.filter(b=>b&&b.type==='text').map(b=>b.text).join('\n');
  return j.output ?? j.text ?? j.content ?? j.response ?? (j.message && j.message.content);
}
let raw = llmText($json);
if (raw===undefined||raw===null||raw==='') raw = JSON.stringify($json);
if (typeof raw==='object') raw = JSON.stringify(raw);
raw = String(raw).trim().replace(/^\`\`\`(?:json)?\s*/i,'').replace(/\`\`\`\s*$/,'').trim();

let p={};
try { p = JSON.parse(raw); }
catch(e){ const m = raw.match(/\{[\s\S]*\}/); if(m){ try{ p = JSON.parse(m[0]); }catch(e2){ p={parse_error:e2.message}; } } else { p={parse_error:e.message}; } }

// --- police: force a BARE font name from the demo.html whitelist -------------
const POLICES = ["Playfair Display","Montserrat","Georgia","Raleway","Oswald","Lobster","Arial"];
function cleanFont(v){
  if (!v) return '';
  let s = String(v);
  s = s.replace(/\([^)]*\)/g, ' ');                       // drop "(serif chaleureuse...)"
  s = s.replace(/\b(bold|black|light|medium|regular|semibold|italic|thin|extrabold)\b/gi,' ');
  s = s.replace(/[,;:].*$/, ' ');                         // drop anything after a separator
  s = s.replace(/\s+/g,' ').trim();
  const hit = POLICES.find(f => f.toLowerCase() === s.toLowerCase())
           || POLICES.find(f => s.toLowerCase().includes(f.toLowerCase()))
           || POLICES.find(f => f.toLowerCase().includes(s.toLowerCase()));
  return hit || '';
}
let police = cleanFont(p.police) || cleanFont(p.fonts && p.fonts.heading) || 'Playfair Display';

const grade = (p.grade_block || '').toString().trim() ||
  'Consistent grade across the whole set: natural daylight, warm-neutral white balance, soft directional light, muted palette, fine film grain, shallow depth of field. Square 1:1. Absolutely no text, no lettering, no words, no numbers, no logo, no watermark, no graphic overlay, no badge, no sticker, no price tag, no border, no collage.';

let tiles = Array.isArray(p.tiles) ? p.tiles.slice(0,9) : [];
// Never emit a short grid: pad deterministically rather than failing the run.
const PAD = ['tight overhead crop of a grilled fish on a matte ceramic plate on dark wood',
             'a leafy restaurant terrace, dappled light, no people',
             'close still life of limes, herbs and chilli on worn wood',
             'a rustic pot of slow-cooked stew beside steamed rice',
             'a terrace at golden hour, silhouettes, warm string lights',
             'macro of a cold cocktail glass with condensation and citrus peel',
             'overhead of a shared table of small plates, cropped at the edges',
             'warm interior: wooden bar, hanging plants, brass lamps at dusk',
             'texture study: folded linen napkin, brass fork, one flower'];
while (tiles.length < 9) { const i = tiles.length; tiles.push({position:i+1, role:'photo', kind:'photo', prompt:PAD[i], ligne:''}); }

const out = tiles.map((t,i) => ({ json: {
  position: i+1,
  kind: (t.kind === 'texte') ? 'texte' : 'photo',
  ligne: (t.ligne || '').toString().slice(0,60),
  tilePrompt: ((t.prompt || PAD[i]).toString() + '\n\n' + grade),
  // carried on every item so the final Sheet write can read them off item 0
  feed_theme: p.feed_theme || '',
  police: police,
  palette: JSON.stringify(p.palette || []),
  grade_block: grade,
  llm_ok: !!(p.tiles && p.tiles.length),
  feedDetailsJson: JSON.stringify({ ...p, police_normalisee: police }, null, 2)
}}));

return out;

const data = $json.data || {};
let urls = [];
try { urls = JSON.parse(data.resultJson).resultUrls || []; } catch (e) {}
const imageUrl = urls[0] || '';
const tile = $('Loop Over Tiles').item.json;
const rawBiz = ($('Route Source').first().json.businessName || 'lead').toString();
const biz = rawBiz.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,40) || 'lead';
const ts = new Date().toISOString().replace(/[^0-9]/g,'').slice(0,8);
const fileName = 'feed-' + biz + '-' + ts + '-t' + String(tile.position).padStart(2,'0') + '.png';
return { json: { imageUrl, fileName, position: tile.position, kind: tile.kind, ligne: tile.ligne } };

const e = $('Extract Image URL').item.json;
return { json: {
  position: e.position,
  kind: e.kind,
  ligne: e.ligne,
  url: 'https://assets.automatisationboost.com/' + e.fileName
} };
